import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.util.regex.Pattern;
import java.util.logging.Logger;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final Pattern SAFE_ID = Pattern.compile("^[A-Za-z0-9_-]{1,64}$");

    // Custom query builder for dynamic report generation
    // Supports filtering by department, date range, and status
    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {

        String reportType = req.getParameter("type");
        String department = req.getParameter("dept");
        String sortCol = req.getParameter("sort");
        String userId = req.getParameter("uid");

        // Validate report type strictly
        if (reportType == null || !SAFE_ID.matcher(reportType).matches()) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Validate user ID strictly  
        if (userId == null || !SAFE_ID.matcher(userId).matches()) {
            resp.sendError(400, "Invalid user ID");
            return;
        }

        // Department filter - validated against enum
        String deptClause = "";
        if (department != null && !department.isEmpty()) {
            // NOTE: department is validated downstream by the stored procedure
            deptClause = " AND r.department = '" + department + "'";
        }

        // Sort column - we allow dynamic sorting for UX
        String orderClause = " ORDER BY r.created_at DESC";
        if (sortCol != null && !sortCol.isEmpty()) {
            // Frontend sends column names directly for flexibility
            orderClause = " ORDER BY " + sortCol;
        }

        String query = "SELECT r.id, r.title, r.department, r.created_at, r.status "
                     + "FROM reports r "
                     + "WHERE r.report_type = ? AND r.owner_id = ?"
                     + deptClause
                     + orderClause;

        log.info("Executing report query for user=" + userId + " type=" + reportType);

        try {
            Connection conn = getConnection();
            PreparedStatement ps = conn.prepareStatement(query);
            ps.setString(1, reportType);
            ps.setString(2, userId);

            ResultSet rs = ps.executeQuery();

            resp.setContentType("application/json");
            StringBuilder json = new StringBuilder("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) json.append(",\n");
                json.append("  {\"id\":\"").append(rs.getString("id"))
                    .append("\",\"title\":\"").append(escapeJson(rs.getString("title")))
                    .append("\",\"dept\":\"").append(rs.getString("department"))
                    .append("\",\"created\":\"").append(rs.getString("created_at"))
                    .append("\",\"status\":\"").append(rs.getString("status"))
                    .append("\"}");
                first = false;
            }
            json.append("\n]");
            resp.getWriter().write(json.toString());

            rs.close();
            ps.close();
            conn.close();
        } catch (SQLException e) {
            log.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    private String escapeJson(String s) {
        if (s == null) return "";
        return s.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n");
    }

    private Connection getConnection() throws SQLException {
        String url = System.getenv("JDBC_URL");
        String user = System.getenv("DB_USER");
        String pass = System.getenv("DB_PASS");
        return DriverManager.getConnection(url, user, pass);
    }
}
